mapper.select:
SELECT id, name, owner, stage, last_stage, contact, phone, products, organization_id, collection_time, in_shared_pool, transition_type, transition_id, follower, follow_time, pool_id, reason_id, create_user, update_user, create_time, update_time FROM clue WHERE organization_id = #{orgId}
AND in_shared_pool = #{inSharedPool}
AND owner IN
#{ownerId}
AND (name LIKE CONCAT('%', #{keyword}, '%') OR contact LIKE CONCAT('%', #{keyword}, '%') OR phone LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY create_time DESC
